// FAL FFmpeg API /compose endpoint payload construction (tracks format)
// Phase4bと同じ形式を使用して、response_urlにGETリクエストを送信した際に正しいレスポンスが返るようにする

// Aggregate Videosノードの出力はvideo_urlの配列のみなので、
// 元の入力データ（Execute Workflow Trigger）からdurationを取得する
const aggregateOutput = $input.first().json;
const videoUrls = aggregateOutput.video_url || [];

// notionPageId または script_id の両方に対応
const scriptId = $('Execute Workflow Trigger').item.json.notionPageId || $('Execute Workflow Trigger').item.json.script_id || 'unknown';

if (!Array.isArray(videoUrls) || videoUrls.length === 0) {
  throw new Error('video_url must be a non-empty array');
}

// 元の入力データからdurationを取得
const originalInput = $('Execute Workflow Trigger').all();

let cumulativeTime = 0;
const keyframes = videoUrls.map((url, index) => {
  // 元の入力データから対応するdurationを取得
  const duration = originalInput[index]?.json?.duration || 5;
  const timestamp = cumulativeTime;

  // 次のタイムスタンプ用に累積時間を更新
  cumulativeTime += duration;

  return {
    url: url,
    timestamp: timestamp,
    duration: duration
  };
});

// Phase4b形式（tracks）のペイロード
const payload = {
  tracks: [{
    id: "1",
    type: "video",
    keyframes: keyframes
  }]
};

return [{ json: { ...payload, script_id: scriptId } }];

// アプローチ1: Fetch Statusのレスポンスから直接動画URLを抽出
// ステータスがCOMPLETEDの場合、レスポンスに動画URLが含まれている可能性
const statusData = $input.first().json;

// デバッグ用: レスポンス構造をログ出力
console.log('Fetch Status response keys:', Object.keys(statusData));
console.log('Fetch Status response preview:', JSON.stringify(statusData).substring(0, 500));

// 動画URL抽出の試行（複数のパターン）
let videoUrl = statusData.output?.video_url
  || statusData.output?.video?.url
  || statusData.output?.url
  || statusData.video_url
  || statusData.result?.video_url
  || statusData.video?.url
  || (statusData.url && !statusData.url.includes('/requests/') && !statusData.url.includes('/status'));

// アプローチ2: response_urlにGETリクエストを送信する必要がある場合のフラグ
// 修正: boolean型に変換（文字列ではなく）
const needsGetRequest = Boolean(!videoUrl && statusData.response_url);

return [{
  json: {
    video_url: videoUrl || null,
    needs_get_request: needsGetRequest,
    response_url: statusData.response_url,
    request_id: statusData.request_id,
    raw_status_response: statusData,
    script_id: $('ペイロード構築').item.json.script_id || 'unknown'
  }
}];

// アプローチ2: response_urlのGETレスポンスから動画URLを抽出
// エラーハンドリングを追加（422エラーの場合、アプローチ4（POST）を試す）
const resultData = $input.first().json;

// デバッグ用: レスポンス構造をログ出力
console.log('Get Result response keys:', Object.keys(resultData));
console.log('Get Result response preview:', JSON.stringify(resultData).substring(0, 500));

// エラーレスポンスの場合（422エラーなど）
if (resultData.detail || resultData.error) {
  // エラーメッセージから動画URLを抽出できない場合、nullを返す
  console.warn('Get Result returned error:', JSON.stringify(resultData));

  // 422エラーの場合、アプローチ4（POSTリクエスト）を試す
  const attempt1Data = $('Extract Video URL (Attempt 1)').item.json;
  const errorDetail = resultData.detail || resultData.error;
  const is422Error = Array.isArray(errorDetail) && errorDetail.some(e => e.loc && e.loc.includes('tracks')) || 
                     (typeof errorDetail === 'string' && errorDetail.includes('tracks'));
  const needsPostRequest = Boolean(is422Error && attempt1Data.raw_status_response?.response_url);

  return [{
    json: {
      video_url: null,
      error: resultData.detail || resultData.error,
      needs_post_request: needsPostRequest,
      needs_status_url_request: !needsPostRequest && Boolean(attempt1Data.raw_status_response?.status_url),
      request_id: attempt1Data.request_id,
      script_id: attempt1Data.script_id || 'unknown'
    }
  }];
}

// 動画URL抽出（成功実例パターン）
let videoUrl = resultData.output?.video_url
  || resultData.output?.video?.url
  || resultData.output?.url
  || resultData.video_url
  || resultData.result?.video_url
  || resultData.video?.url
  || (resultData.url && !resultData.url.includes('/requests/') && !resultData.url.includes('/status'));

if (!videoUrl) {
  const availableKeys = Object.keys(resultData);
  const responsePreview = JSON.stringify(resultData, null, 2).substring(0, 2000);
  console.warn('Video URL not found in response_url GET response');
  console.warn('Available keys:', availableKeys);
  console.warn('Response preview:', responsePreview);

  // アプローチ3が必要かチェック（status_urlがある場合）
  const attempt1Data = $('Extract Video URL (Attempt 1)').item.json;
  const needsStatusUrlRequest = Boolean(attempt1Data.raw_status_response?.status_url);

  return [{
    json: {
      video_url: null,
      error: 'Video URL not found in response_url GET response',
      needs_post_request: false,
      needs_status_url_request: needsStatusUrlRequest,
      raw_response: resultData,
      request_id: attempt1Data.request_id,
      script_id: attempt1Data.script_id || 'unknown'
    }
  }];
}

return [{
  json: {
    video_url: videoUrl,
    needs_post_request: false,
    needs_status_url_request: false,
    raw_response: resultData,
    request_id: $('Extract Video URL (Attempt 1)').item.json.request_id,
    script_id: $('Extract Video URL (Attempt 1)').item.json.script_id || 'unknown'
  }
}];

// ペイロード変換: オプション1実装後、ペイロード構築ノードの出力はすでにtracks形式
// そのまま使用する（変換不要）
const phase4cPayload = $('ペイロード構築').item.json;
const attempt1Data = $('Extract Video URL (Attempt 1)').item.json;

// オプション1実装後は、ペイロード構築ノードの出力がすでにtracks形式
// そのまま使用する（script_idは除外）
const tracksPayload = {
  tracks: phase4cPayload.tracks || [{
    id: "1",
    type: "video",
    keyframes: []
  }]
};

return [{
  json: {
    payload: tracksPayload,
    response_url: attempt1Data.raw_status_response.response_url,
    request_id: attempt1Data.request_id,
    script_id: attempt1Data.script_id || 'unknown'
  }
}];

// アプローチ4: response_urlのPOSTレスポンスから動画URLを抽出
const resultData = $input.first().json;

// デバッグ用: レスポンス構造をログ出力
console.log('Get Result (Approach 4) response keys:', Object.keys(resultData));
console.log('Get Result (Approach 4) response preview:', JSON.stringify(resultData).substring(0, 500));

// エラーレスポンスの場合
if (resultData.detail || resultData.error) {
  console.warn('Get Result (Approach 4) returned error:', JSON.stringify(resultData));
  const attempt1Data = $('Extract Video URL (Attempt 1)').item.json;
  return [{
    json: {
      video_url: null,
      error: resultData.detail || resultData.error,
      request_id: attempt1Data.request_id,
      script_id: attempt1Data.script_id || 'unknown'
    }
  }];
}

// 動画URL抽出（複数のパターンを試す）
let videoUrl = resultData.output?.video_url
  || resultData.output?.video?.url
  || resultData.output?.url
  || resultData.video_url
  || resultData.result?.video_url
  || resultData.video?.url
  || (resultData.url && !resultData.url.includes('/requests/') && !resultData.url.includes('/status'));

if (!videoUrl) {
  const availableKeys = Object.keys(resultData);
  const responsePreview = JSON.stringify(resultData, null, 2).substring(0, 2000);
  console.warn('Video URL not found in response_url POST response');
  console.warn('Available keys:', availableKeys);
  console.warn('Response preview:', responsePreview);
  const attempt1Data = $('Extract Video URL (Attempt 1)').item.json;
  return [{
    json: {
      video_url: null,
      error: 'Video URL not found in response_url POST response',
      raw_response: resultData,
      request_id: attempt1Data.request_id,
      script_id: attempt1Data.script_id || 'unknown'
    }
  }];
}

const attempt1Data = $('Extract Video URL (Attempt 1)').item.json;
return [{
  json: {
    video_url: videoUrl,
    raw_response: resultData,
    request_id: attempt1Data.request_id,
    script_id: attempt1Data.script_id || 'unknown'
  }
}];

// アプローチ3: status_urlのGETレスポンスから動画URLを抽出
const resultData = $input.first().json;

// デバッグ用: レスポンス構造をログ出力
console.log('Get Status URL response keys:', Object.keys(resultData));
console.log('Get Status URL response preview:', JSON.stringify(resultData).substring(0, 500));

// エラーレスポンスの場合
if (resultData.detail || resultData.error) {
  console.warn('Get Status URL returned error:', JSON.stringify(resultData));
  const attempt1Data = $('Extract Video URL (Attempt 1)').item.json;
  return [{
    json: {
      video_url: null,
      error: resultData.detail || resultData.error,
      request_id: attempt1Data.request_id,
      script_id: attempt1Data.script_id || 'unknown'
    }
  }];
}

// 動画URL抽出（複数のパターンを試す）
let videoUrl = resultData.output?.video_url
  || resultData.output?.video?.url
  || resultData.output?.url
  || resultData.video_url
  || resultData.result?.video_url
  || resultData.video?.url
  || (resultData.url && !resultData.url.includes('/requests/') && !resultData.url.includes('/status'));

if (!videoUrl) {
  const availableKeys = Object.keys(resultData);
  const responsePreview = JSON.stringify(resultData, null, 2).substring(0, 2000);
  console.warn('Video URL not found in status_url GET response');
  console.warn('Available keys:', availableKeys);
  console.warn('Response preview:', responsePreview);
  const attempt1Data = $('Extract Video URL (Attempt 1)').item.json;
  return [{
    json: {
      video_url: null,
      error: 'Video URL not found in status_url GET response',
      raw_response: resultData,
      request_id: attempt1Data.request_id,
      script_id: attempt1Data.script_id || 'unknown'
    }
  }];
}

const attempt1Data = $('Extract Video URL (Attempt 1)').item.json;
return [{
  json: {
    video_url: videoUrl,
    raw_response: resultData,
    request_id: attempt1Data.request_id,
    script_id: attempt1Data.script_id || 'unknown'
  }
}];

// 動画URLを統合（アプローチ1、アプローチ2、アプローチ4、またはアプローチ3の結果）
// エラーハンドリングを改善
const attempt1Data = $('Extract Video URL (Attempt 1)').item.json;

// アプローチ1で動画URLが取得できた場合
if (attempt1Data.video_url) {
  return [{
    json: {
      video_url: attempt1Data.video_url,
      request_id: attempt1Data.request_id,
      script_id: attempt1Data.script_id,
      approach: 'status_response_direct'
    }
  }];
}

// アプローチ2の結果を確認（Needs POST Request?のfalse分岐から来る場合）
let attempt2Data = null;
try {
  const attempt2Node = $('Extract Video URL (Attempt 2)');
  if (attempt2Node && attempt2Node.item) {
    attempt2Data = attempt2Node.item.json;
  }
} catch (e) {
  // アプローチ2が実行されていない場合（アプローチ1で成功した場合）
}

// アプローチ2で動画URLが取得できた場合
if (attempt2Data && attempt2Data.video_url) {
  return [{
    json: {
      video_url: attempt2Data.video_url,
      request_id: attempt2Data.request_id,
      script_id: attempt2Data.script_id,
      approach: 'response_url_get'
    }
  }];
}

// アプローチ4の結果を確認（Needs POST Request?のtrue分岐から来る場合）
let attempt4Data = null;
try {
  const attempt4Node = $('Extract Video URL (Attempt 4)');
  if (attempt4Node && attempt4Node.item) {
    attempt4Data = attempt4Node.item.json;
  }
} catch (e) {
  // アプローチ4が実行されていない場合
}

// アプローチ4で動画URLが取得できた場合
if (attempt4Data && attempt4Data.video_url) {
  return [{
    json: {
      video_url: attempt4Data.video_url,
      request_id: attempt4Data.request_id,
      script_id: attempt4Data.script_id,
      approach: 'response_url_post'
    }
  }];
}

// アプローチ3の結果を確認（Needs Status URL Request?のtrue分岐から来る場合）
let attempt3Data = null;
try {
  const attempt3Node = $('Extract Video URL (Attempt 3)');
  if (attempt3Node && attempt3Node.item) {
    attempt3Data = attempt3Node.item.json;
  }
} catch (e) {
  // アプローチ3が実行されていない場合
}

// アプローチ3で動画URLが取得できた場合
if (attempt3Data && attempt3Data.video_url) {
  return [{
    json: {
      video_url: attempt3Data.video_url,
      request_id: attempt3Data.request_id,
      script_id: attempt3Data.script_id,
      approach: 'status_url_get'
    }
  }];
}

// どれも失敗した場合、詳細なエラーメッセージを返す
const errorDetails = {
  attempt1: {
    video_url: attempt1Data.video_url,
    needs_get_request: attempt1Data.needs_get_request,
    response_keys: Object.keys(attempt1Data.raw_status_response || {})
  },
  attempt2: attempt2Data ? (attempt2Data.error ? {
    error: attempt2Data.error,
    raw_response_keys: Object.keys(attempt2Data.raw_response || {})
  } : {
    video_url: attempt2Data.video_url,
    raw_response_keys: Object.keys(attempt2Data.raw_response || {})
  }) : 'not executed',
  attempt4: attempt4Data ? (attempt4Data.error ? {
    error: attempt4Data.error,
    raw_response_keys: Object.keys(attempt4Data.raw_response || {})
  } : {
    video_url: attempt4Data.video_url,
    raw_response_keys: Object.keys(attempt4Data.raw_response || {})
  }) : 'not executed',
  attempt3: attempt3Data ? (attempt3Data.error ? {
    error: attempt3Data.error,
    raw_response_keys: Object.keys(attempt3Data.raw_response || {})
  } : {
    video_url: attempt3Data.video_url,
    raw_response_keys: Object.keys(attempt3Data.raw_response || {})
  }) : 'not executed'
};

throw new Error(
  'Video URL not found in all approaches.\n' +
  'Attempt 1 (status response): ' + JSON.stringify(errorDetails.attempt1, null, 2) + '\n' +
  'Attempt 2 (response_url GET): ' + JSON.stringify(errorDetails.attempt2, null, 2) + '\n' +
  'Attempt 4 (response_url POST): ' + JSON.stringify(errorDetails.attempt4, null, 2) + '\n' +
  'Attempt 3 (status_url GET): ' + JSON.stringify(errorDetails.attempt3, null, 2)
);

// ファイル名を構築
const scriptId = $('ペイロード構築').item.json.script_id || 'unknown';
const now = new Date();
const timestamp = now.toISOString().replace(/[-:]/g, '').replace(/T/, '_').substring(0, 15);
const filename = `WF7_Final_${scriptId}_${timestamp}.mp4`;

return [{
  json: {
    ...$input.first().json,
    filename: filename,
    script_id: scriptId
  },
  binary: $input.first().binary
}];
